use serde_json::{json,Value};
use std::{collections::BTreeMap,env,fs};
fn comparable(mut v:Value)->Value {
 v["stats"].as_array_mut().unwrap().retain(|x|x[0]!="wall_total");
 for p in v["phases"].as_array_mut().unwrap(){let descent=p["phase"]=="descent";let m=p.as_object_mut().unwrap();m.remove("wall");if descent{for k in["mul","inv","add","lmul","ladd","hash","cmp"]{m.remove(k);}}}v
}
#[derive(Default)]
struct Group{pairs:u64,ok:u64,failures:Vec<String>,original:BTreeMap<String,u64>,candidate:BTreeMap<String,u64>,calls:BTreeMap<String,u64>}
fn totals(report:&Value,out:&mut BTreeMap<String,u64>){for p in report["phases"].as_array().unwrap(){for k in["mul","inv","add","lmul","ladd","hash","cmp"]{*out.entry(k.to_owned()).or_default()+=p[k].as_u64().unwrap();}}}
fn main(){let a=env::args().collect::<Vec<_>>();assert_eq!(a.len(),3);let rows:Vec<Value>=serde_json::from_slice(&fs::read(&a[1]).unwrap()).unwrap();let mut counts=BTreeMap::<String,u64>::new();let mut groups=BTreeMap::<(u64,u64),Group>::new();let mut inputs=Vec::new();let mut cases=Vec::new();let mut scope=None;let mut scalar_pairs=0;let mut triples=0;
 for row in &rows {let k=row["kind"].as_str().unwrap();let d=&row["data"];*counts.entry(k.to_owned()).or_default()+=1;match k{
  "N4_ORIGINAL_FIXED_SAMPLER_INPUT"=>{assert_eq!(d["strong_known_point_reference_exact"],true);assert_eq!(d["prepared_public_source"],d["independent_already_known_source_point"]);inputs.push(d.clone());},
  "N4_ORIGINAL_FIXED_SAMPLER_SCALARS"=>{assert_eq!(d["all75"].as_array().unwrap().len(),75);for s in d["all75"].as_array().unwrap(){assert_eq!(s["sampler_class"],s["original_Picard_class"]);scalar_pairs+=1;for t in s["all_five_triples"].as_array().unwrap(){assert_eq!(t["all_three_exact"],true);triples+=1;}}},
  "N4_ORIGINAL_FIXED_SAMPLER_ATTEMPT"=>{let side=d["side"].as_u64().unwrap();let fb=d["nfb"].as_u64().unwrap();let old=&d["original"];let new=&d["candidate"];assert_eq!(comparable(old.clone()),comparable(new.clone()));let g=groups.entry((side,fb)).or_default();g.pairs+=1;
   if old["ok"]==true {assert_eq!(new["ok"],true);for k in["original_target_group_check","candidate_target_group_check","original_source_check","candidate_source_check"]{assert_eq!(d[k],true);}g.ok+=1;}else{assert_eq!(new["ok"],false);assert_eq!(old["fail"],new["fail"]);g.failures.push(old["fail"].as_str().unwrap().to_owned());}
   totals(old,&mut g.original);totals(new,&mut g.candidate);for(k,v)in d["explicit_candidate_calls"].as_object().unwrap(){*g.calls.entry(k.clone()).or_default()+=v.as_u64().unwrap();}
  },
  "N4_ORIGINAL_FIXED_SAMPLER_CASE"=>cases.push(d.clone()),
  "N4_ORIGINAL_FIXED_SAMPLER_SCOPE"=>{assert!(scope.is_none());scope=Some(d.clone());},_=>{},
 }}assert_eq!(scalar_pairs,225);assert_eq!(triples,1125);assert_eq!(inputs.len(),3);assert_eq!(cases.len(),15);assert_eq!(groups.len(),12);let scope=scope.unwrap();assert_eq!(scope["common_solved_cases"],15);let mut paired=0;let mut joint_ok=0;let mut table=Vec::new();for((side,nfb),g)in groups{assert_eq!(g.pairs,5);paired+=g.pairs;joint_ok+=g.ok;table.push(json!({"side":side,"nfb":nfb,"all_pairs":g.pairs,"joint_verified_successes":g.ok,"shared_rejected_pairs":g.pairs-g.ok,"all_shared_failure_reasons":g.failures,"original_partial_counters":g.original,"candidate_partial_counters":g.candidate,"all_candidate_API_calls":g.calls,"scope":"allfivepairedattempts/fullreports retained; partial counters and API entries exclude complete FpR/setup/nested/verification/reference costs, not a calibrated ratio"}));}assert_eq!(paired,60);
 fs::write(&a[2],serde_json::to_vec_pretty(&json!({"whole_record_count":rows.len(),"every_record_kind_count":counts,"all_three_public_inputs_and_known_point_references":inputs,"all15_joint_public_case_records":cases,"actual_Rust_scope":scope,"all12_setting_groups":table,"scalar_pairs":scalar_pairs,"class_triples":triples,"paired_attempts":paired,"whole_solver_reports":2*paired,"joint_verified_successful_pairs":joint_ok,"verified_successful_reports":2*joint_ok,"shared_rejected_pairs":paired-joint_ok,"rejected_reports":2*(paired-joint_ok),"all_frozen_comparison_fields_independently_equal":true,"all_three_derived_sources_exact_independent_known_initial_points":true,"strong_reference_finding":"After preparation sample(r)=Phi([r]u) has the same source point and operation body as sampling from the already available transported generator. Public norm preparation supplies no newly demonstrated advantage over that stronger known-point reference; complete costs and admission remain open.","complete_costs":"unknown; no calibrated ratio, ECDLP advantage or new asymptotic result","scope":"Rust exact whole-record aggregation and independent frozen-projection comparison; full raw data is never filtered"})).unwrap()).unwrap();}
